def preserve_requests_and_disable_personal_login(apps, schema_editor):
    ShiftRequest=apps.get_model('scheduling','ShiftRequest')
    AccountProfile=apps.get_model('scheduling','AccountProfile')
    User=apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    for item in ShiftRequest.objects.select_related('nurse','partner').all().iterator():
        if item.nurse_id:
            item.group_id=item.nurse.group_id
            item.nurse_id_at_request=item.nurse_id
            item.nurse_name_at_request=item.nurse.name
            item.nurse_employee_at_request=item.nurse.employee_id
        if item.partner_id:
            item.partner_id_at_request=item.partner_id
            item.partner_name_at_request=item.partner.name
        item.save(update_fields=['group','nurse_id_at_request','nurse_name_at_request','nurse_employee_at_request',
            'partner_id_at_request','partner_name_at_request'])
    profile_ids=list(AccountProfile.objects.filter(role='nurse',user__is_superuser=False).values_list('user_id',flat=True))
    User.objects.filter(pk__in=profile_ids).update(is_active=False)
    AccountProfile.objects.filter(role='nurse',user__is_superuser=False).update(role='disabled_nurse')
    AccountProfile.objects.filter(role='nurse',user__is_superuser=True).update(role='system_admin')


